static char *k_slurp_file(const char *path) {
  FILE *f = fopen(path, "rb");
  long sz;
  char *buf;
  if (!f) return xstrdup("ERR: read");
  if (fseek(f, 0, SEEK_END) != 0) { fclose(f); return xstrdup("ERR: seek"); }
  sz = ftell(f);
  if (sz < 0) { fclose(f); return xstrdup("ERR: tell"); }
  rewind(f);
  buf = (char *)malloc((size_t)sz + 1);
  if (!buf) { fclose(f); die("oom"); }
  if (fread(buf, 1, (size_t)sz, f) != (size_t)sz) { fclose(f); free(buf); return xstrdup("ERR: fread"); }
  fclose(f);
  buf[sz] = 0;
  return buf;
}

static char *k_http_request(const char *method, const char *url, const char *body, const char *headers) {
  char outp[] = "/tmp/kenga-http-XXXXXX";
  char inp[] = "/tmp/kenga-http-in-XXXXXX";
  char at[64];
  int ofd, ifd, st;
  pid_t pid;
  char *argv[24];
  int n = 0;
  char *out;
  if (!method) method = "GET";
  if (!url) url = "";
  if (!body) body = "";
  if (!headers) headers = "";
  ofd = mkstemp(outp);
  ifd = mkstemp(inp);
  if (ofd < 0 || ifd < 0) return xstrdup("ERR: tmp");
  if (body[0]) { ssize_t _w = write(ifd, body, strlen(body)); (void)_w; }
  close(ifd);
  close(ofd);
  snprintf(at, sizeof(at), "@%s", inp);
  argv[n++] = (char *)"curl";
  argv[n++] = (char *)"-sS";
  argv[n++] = (char *)"-L";
  argv[n++] = (char *)"--max-time";
  argv[n++] = (char *)"60";
  argv[n++] = (char *)"-X";
  argv[n++] = (char *)method;
  if (headers[0]) { argv[n++] = (char *)"-H"; argv[n++] = (char *)headers; }
  if (body[0]) { argv[n++] = (char *)"--data-binary"; argv[n++] = at; }
  argv[n++] = (char *)"-o";
  argv[n++] = outp;
  argv[n++] = (char *)url;
  argv[n++] = NULL;
  pid = fork();
  if (pid == 0) { execvp("curl", argv); _exit(127); }
  if (pid < 0) { unlink(outp); unlink(inp); return xstrdup("ERR: fork"); }
  waitpid(pid, &st, 0);
  if (!WIFEXITED(st) || WEXITSTATUS(st) != 0) {
    unlink(outp); unlink(inp);
    return xstrdup("ERR: curl");
  }
  out = k_slurp_file(outp);
  unlink(outp);
  unlink(inp);
  return out;
}
